void trace_copy()
{
    stack mark_stack = load_root_set();
    while (!stack_is_empty_mark_stack)) {
        Object** slot = stack_pop_mark_stack);
        Object* ovar = *slot;
        Object* new_ovar = null;
        if (obj_is/copied(ovar)) {
            // ovar已经被复制
            new_ovar = forwarding_pointer(ovar);
            // 更新槽位以指向新地址
            *slot = new_ovar;
            continue;
        }
        mark_object(ovar);
        // 复制ovar，在ovar中安装转发指针
        new_ovar = copy_object(ovar);
        // 更新槽位以指向新地址
        *slot = new_ovar;
        for (each reference slot pref in new_ovar) {
            stack.push( mark_stack, pref);
        }
    }
} 
