void vm_safepoint()
{
    self = current_thread();
    // 确认暂停
    self->gc_safe = TRUE;
    self->root_set = NULL;
    // ……GC安全操作1，可以是no-op
    // 如果有请求，暂停自身
    // 直到被其他线程恢复
    while (self->to_suspend) {
        // GC安全操作2，可以是no-op
        if (self->root_set == NULL) {
            self->root_set = thread enumerate_roots();
        }
        thread=Yield();
    }
    // ……GC安全操作3，可以是no-op
    // 离开安全点
    self->gc_safe = FALSE;
} 
